def parse_json(s: str) -> object:
    """
    Parse a JSON string into appropriate Python objects using a recursive descent parsing technique.
    This function handles strings, numbers, booleans, null, arrays, and objects.
    """

    pos = 0

    def next_char():
        nonlocal pos
        if pos < len(s):
            char = s[pos]
            pos += 1
            return char
        return None

    def skip_whitespace():
        while pos < len(s) and s[pos].isspace():
            next_char()

    def parse_value():
        skip_whitespace()
        c = next_char()
        if c == '"':
            return parse_string()
        elif c.isdigit() or c == '-':
            return parse_number(c + parse_number_suffix())
        elif c == 't':
            expect('rue')
            return True
        elif c == 'f':
            expect('alse')
            return False
        elif c == 'n':
            expect('ull')
            return None
        elif c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        else:
            raise ValueError(f"Unexpected character: {c}")

    def parse_string():
        result = []
        while True:
            c = next_char()
            if c == '"':
                return ''.join(result)
            elif c == '\\':
                escape_char = next_char()
                if escape_char in '"\\/bfnrt':
                    result.append({
                        '"': '"',
                        '\\': '\\',
                        '/': '/',
                        'b': '\b',
                        'f': '\f',
                        'n': '\n',
                        'r': '\r',
                        't': '\t'
                    }[escape_char])
                else:
                    raise ValueError(f"Invalid escape character: {escape_char}")
            elif c is None:
                raise ValueError("Unexpected end of string")
            else:
                result.append(c)

    def parse_number(first_char):
        number_str = first_char
        while True:
            c = next_char()
            if c is None or c.isspace() or c in ',]}':
                pos -= 1  # Backtrack one character
                break
            number_str += c
        if '.' in number_str:
            return float(number_str)
        return int(number_str)

    def parse_number_suffix():
        result = []
        while True:
            c = next_char()
            if c is None or c.isspace() or c in ',]}':
                pos -= 1
                break
            result.append(c)
        return ''.join(result)

    def parse_object():
        obj = {}
        skip_whitespace()
        while s[pos] != '}':
            key = parse_string()
            skip_whitespace()
            if next_char() != ':':
                raise ValueError("Expected ':' in object")
            value = parse_value()
            obj[key] = value
            skip_whitespace()
            c = next_char()
            if c == '}':
                break
            elif c != ',':
                raise ValueError("Expected ',' or '}' in object")
        return obj

    def parse_array():
        array = []
        skip_whitespace()
        while s[pos] != ']':
            value = parse_value()
            array.append(value)
            skip_whitespace()
            c = next_char()
            if c == ']':
                break
            elif c != ',':
                raise ValueError("Expected ',' or ']' in array")
        return array

    def expect(expected):
        for char in expected:
            c = next_char()
            if c != char:
                raise ValueError(f"Expected '{expected}' but got '{c}'")

    skip_whitespace()
    result = parse_value()
    skip_whitespace()
    if pos != len(s):
        raise ValueError("Extra data after JSON input")
    return result

