    """
    Parse a JSON string into appropriate Python objects using a finite state machine (FSM) approach. 
    This parser iterates through the input string and uses states to determine how to process the current character.
    It handles strings, numbers, booleans, null, arrays, and objects.
    """

    class JSONParser:
        def __init__(self, input_str):
            self.s = input_str
            self.pos = 0
            self.state = self.start_state
            self.result = None
            self.current_value = None
            self.stack = []

        def parse(self):
            while self.pos < len(self.s):
                self.state()
            if self.pos < len(self.s):
                raise ValueError("Extra data after JSON input")
            return self.result

        def start_state(self):
            self.skip_whitespace()
            if self.pos < len(self.s):
                char = self.s[self.pos]
                if char == '{':
                    self.state = self.object_state
                    self.stack.append({})
                elif char == '[':
                    self.state = self.array_state
                    self.stack.append([])
                else:
                    self.value_state()
            else:
                self.finalize()

        def object_state(self):
            self.skip_whitespace()
            if self.s[self.pos] == '}':
                self.finalize()
                return

            key = self.parse_string()
            self.skip_whitespace()
            if self.s[self.pos] != ':':
                raise ValueError("Expected ':' in object")
            self.pos += 1  # skip ':'
            value = self.value_state()
            self.stack[-1][key] = value
            self.skip_whitespace()

            if self.pos < len(self.s) and self.s[self.pos] == '}':
                self.finalize()
            elif self.pos < len(self.s) and self.s[self.pos] == ',':
                self.pos += 1  # skip ','
            else:
                raise ValueError("Expected ',' or '}' in object")

        def array_state(self):
            self.skip_whitespace()
            if self.s[self.pos] == ']':
                self.finalize()
                return

            value = self.value_state()
            self.stack[-1].append(value)
            self.skip_whitespace()

            if self.pos < len(self.s) and self.s[self.pos] == ']':
                self.finalize()
            elif self.pos < len(self.s) and self.s[self.pos] == ',':
                self.pos += 1  # skip ','
            else:
                raise ValueError("Expected ',' or ']' in array")

        def value_state(self):
            self.skip_whitespace()
            if self.pos < len(self.s):
                char = self.s[self.pos]
                if char == '"':
                    return self.parse_string()
                elif char in '-0123456789':
                    return self.parse_number()
                elif self.s.startswith("true", self.pos):
                    self.pos += 4
                    return True
                elif self.s.startswith("false", self.pos):
                    self.pos += 5
                    return False
                elif self.s.startswith("null", self.pos):
                    self.pos += 4
                    return None
                else:
                    raise ValueError(f"Unexpected character '{char}'")
            return None

        def parse_string(self):
            result = []
            self.pos += 1  # skip opening quote
            while self.pos < len(self.s):
                char = self.s[self.pos]
                if char == '"':
                    self.pos += 1  # skip closing quote
                    return ''.join(result)
                elif char == '\\':
                    self.pos += 1  # skip escape character
                    if self.pos < len(self.s):
                        result.append(self.parse_escape_character())
                else:
                    result.append(char)
                self.pos += 1
            raise ValueError("Unclosed string")

        def parse_escape_character(self):
            escape_map = {
                '"': '"',
                '\\': '\\',
                '/': '/',
                'b': '\b',
                'f': '\f',
                'n': '\n',
                'r': '\r',
                't': '\t'
            }
            if self.pos < len(self.s):
                char = self.s[self.pos]
                if char in escape_map:
                    self.pos += 1
                    return escape_map[char]
            raise ValueError("Invalid escape character")

        def parse_number(self):
            start = self.pos
            if self.s[self.pos] in '-0123456789':
                self.pos += 1
                while self.pos < len(self.s) and self.s[self.pos] in '0123456789':
                    self.pos += 1
                if self.pos < len(self.s) and self.s[self.pos] == '.':
                    self.pos += 1
                    if self.pos < len(self.s) and self.s[self.pos] in '0123456789':
                        while self.pos < len(self.s) and self.s[self.pos] in '0123456789':
                            self.pos += 1
                        return float(self.s[start:self.pos])
                    raise ValueError("Invalid number format")
                return int(self.s[start:self.pos])
            raise ValueError("Invalid number format")

        def skip_whitespace(self):
            while self.pos < len(self.s) and self.s[self.pos].isspace():
                self.pos += 1

        def finalize(self):
            if self.stack:
                self.result = self.stack.pop()
            else:
                self.result = None

    parser = JSONParser(s)
    return parser.parse()

def parse_json(s: str) -> object:
    """
    Parse a JSON string into Python objects by implementing a token-based finite-state parser. 
    This approach reads the input string character by character, generates tokens, and uses a stack 
    to build the resulting Python structures (dicts and lists).
    """

    class TokenType:
        STRING = 'STRING'
        NUMBER = 'NUMBER'
        TRUE = 'TRUE'
        FALSE = 'FALSE'
        NULL = 'NULL'
        LBRACE = '{'
        RBRACE = '}'
        LBRACKET = '['
        RBRACKET = ']'
        COLON = ':'
        COMMA = ','
        EOF = 'EOF'


    class Token:
        def __init__(self, type_, value=None):
            self.type = type_
            self.value = value

    pos = 0

    def next_token():
        nonlocal pos
        while pos < len(s) and s[pos].isspace():
            pos += 1

        if pos == len(s):
            return Token(TokenType.EOF)

        char = s[pos]

        if char == '"':
            return Token(TokenType.STRING, parse_string())
        elif char in '-0123456789':
            return Token(TokenType.NUMBER, parse_number())
        elif s.startswith("true", pos):
            pos += 4
            return Token(TokenType.TRUE)
        elif s.startswith("false", pos):
            pos += 5
            return Token(TokenType.FALSE)
        elif s.startswith("null", pos):
            pos += 4
            return Token(TokenType.NULL)
        elif char == '{':
            pos += 1
            return Token(TokenType.LBRACE)
        elif char == '}':
            pos += 1
            return Token(TokenType.RBRACE)
        elif char == '[':
            pos += 1
            return Token(TokenType.LBRACKET)
        elif char == ']':
            pos += 1
            return Token(TokenType.RBRACKET)
        elif char == ':':
            pos += 1
            return Token(TokenType.COLON)
        elif char == ',':
            pos += 1
            return Token(TokenType.COMMA)

        raise ValueError(f"Unexpected character: {char}")

    def parse_string():
        nonlocal pos
        result = []
        pos += 1  # Skip the opening quote

        while pos < len(s):
            char = s[pos]
            if char == '"':
                pos += 1  # Skip closing quote
                return ''.join(result)
            elif char == '\\':
                pos += 1  # Skip the escape character
                if pos < len(s):
                    escape_char = s[pos]
                    escape_map = {
                        '"': '"',
                        '\\': '\\',
                        '/': '/',
                        'b': '\b',
                        'f': '\f',
                        'n': '\n',
                        'r': '\r',
                        't': '\t',
                    }
                    if escape_char in escape_map:
                        result.append(escape_map[escape_char])
                        pos += 1
                    else:
                        raise ValueError(f"Invalid escape character: {escape_char}")
            else:
                result.append(char)
                pos += 1
        raise ValueError("Unclosed string")

    def parse_number():
        nonlocal pos
        start = pos
        if s[pos] in '-0123456789':
            pos += 1
            while pos < len(s) and s[pos] in '0123456789':
                pos += 1
            if pos < len(s) and s[pos] == '.':
                pos += 1
                while pos < len(s) and s[pos] in '0123456789':
                    pos += 1
                return float(s[start:pos])
            return int(s[start:pos])
        raise ValueError("Invalid number format")

    def parse_value():
        token = next_token()
        if token.type == TokenType.STRING:
            return token.value
        elif token.type == TokenType.NUMBER:
            return token.value
        elif token.type == TokenType.TRUE:
            return True
        elif token.type == TokenType.FALSE:
            return False
        elif token.type == TokenType.NULL:
            return None
        elif token.type == TokenType.LBRACE:
            return parse_object()
        elif token.type == TokenType.LBRACKET:
            return parse_array()
        raise ValueError("Unexpected token")

    def parse_object():
        obj = {}
        while True:
            token = next_token()
            if token.type == TokenType.RBRACE:
                return obj
            if token.type != TokenType.STRING:
                raise ValueError("Expected string as key in object")
            key = token.value

            token = next_token()
            if token.type != TokenType.COLON:
                raise ValueError("Expected ':' after key in object")
            value = parse_value()
            obj[key] = value

            token = next_token()
            if token.type == TokenType.RBRACE:
                return obj
            elif token.type != TokenType.COMMA:
                raise ValueError("Expected ',' or '}' in object")

    def parse_array():
        array = []
        while True:
            token = next_token()
            if token.type == TokenType.RBRACKET:
                return array
            pos -= len(token.value)  # Move back to read value
            value = parse_value()
            array.append(value)

            token = next_token()
            if token.type == TokenType.RBRACKET:
                return array
            elif token.type != TokenType.COMMA:
                raise ValueError("Expected ',' or ']' in array")

    return parse_value()

