def parse_json(s: str) -> object:
    """
    Parse a JSON string into Python objects using a state machine approach with character buffering. 
    This function handles strings, numbers, booleans, null, arrays, and objects.
    """

    class Parser:
        def __init__(self, input_str):
            self.s = input_str
            self.pos = 0
            self.length = len(input_str)
            self.char = None

        def next_char(self):
            if self.pos < self.length:
                self.char = self.s[self.pos]
                self.pos += 1
            else:
                self.char = None

        def skip_whitespace(self):
            while self.char is not None and self.char.isspace():
                self.next_char()

        def parse(self):
            self.next_char()
            self.skip_whitespace()
            result = self.parse_value()
            self.skip_whitespace()
            if self.char is not None:
                raise ValueError("Extra data after JSON input")
            return result

        def parse_value(self):
            if self.char == '"':
                return self.parse_string()
            elif self.char in '-0123456789':
                return self.parse_number()
            elif self.char == 't':
                self.expect("rue")
                return True
            elif self.char == 'f':
                self.expect("alse")
                return False
            elif self.char == 'n':
                self.expect("ull")
                return None
            elif self.char == '{':
                return self.parse_object()
            elif self.char == '[':
                return self.parse_array()
            else:
                raise ValueError(f"Unexpected character: {self.char}")

        def parse_string(self):
            self.next_char()  # Skip opening quote
            result = []
            while self.char is not None:
                if self.char == '"':
                    self.next_char()  # Skip closing quote
                    return ''.join(result)
                elif self.char == '\\':
                    self.next_char()  # Skip escape character
                    if self.char in '\"\\/bfnrt':
                        escape_map = {
                            '"': '"',
                            '\\': '\\',
                            '/': '/',
                            'b': '\b',
                            'f': '\f',
                            'n': '\n',
                            'r': '\r',
                            't': '\t',
                        }
                        result.append(escape_map[self.char])
                    else:
                        raise ValueError(f"Invalid escape character: {self.char}")
                else:
                    result.append(self.char)
                self.next_char()
            raise ValueError("Unclosed string")

        def parse_number(self):
            start = self.pos - 1
            if self.char == '-':
                self.next_char()
            while self.char is not None and self.char.isdigit():
                self.next_char()
            if self.char == '.':
                self.next_char()
                if self.char is None or not self.char.isdigit():
                    raise ValueError("Invalid number format")
                while self.char is not None and self.char.isdigit():
                    self.next_char()
                return float(self.s[start:self.pos])
            return int(self.s[start:self.pos])

        def parse_object(self):
            self.next_char()  # Skip '{'
            obj = {}
            self.skip_whitespace()
            while self.char is not None and self.char != '}':
                key = self.parse_string()
                self.skip_whitespace()
                if self.char != ':':
                    raise ValueError("Expected ':' after key")
                self.next_char()  # Skip ':'
                value = self.parse_value()
                obj[key] = value
                self.skip_whitespace()
                if self.char == ',':
                    self.next_char()  # Skip ','
                    self.skip_whitespace()
                elif self.char != '}':
                    raise ValueError("Expected ',' or '}' in object")
            self.next_char()  # Skip '}'
            return obj

        def parse_array(self):
            self.next_char()  # Skip '['
            array = []
            self.skip_whitespace()
            while self.char is not None and self.char != ']':
                value = self.parse_value()
                array.append(value)
                self.skip_whitespace()
                if self.char == ',':
                    self.next_char()  # Skip ','
                    self.skip_whitespace()
                elif self.char != ']':
                    raise ValueError("Expected ',' or ']' in array")
            self.next_char()  # Skip ']'
            return array

        def expect(self, expected):
            for char in expected:
                if self.char != char:
                    raise ValueError(f"Expected '{expected}' but got '{self.char}'")
                self.next_char()

    parser = Parser(s)
    return parser.parse()
